/// <summary>Searches the web via DuckDuckGo HTML and returns result snippets.</summary>
sealed class WebSearch
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a list of result snippets with titles and URLs.")]
    public async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        try
        {
            var html = await s_http.GetStringAsync(url);
            return ParseResults(html);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseResults(string html)
    {
        var sb = new StringBuilder();
        var resultPattern = ResultRegex();
        var snippetPattern = SnippetRegex();
        var tagStripper = TagStripperRegex();

        var results = resultPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        var count = Math.Min(results.Count, 5);
        if (count == 0)
        {
            return "No results found.";
        }

        for (var i = 0; i < count; i++)
        {
            var title = tagStripper.Replace(results[i].Groups[2].Value, "").Trim();
            var link = results[i].Groups[1].Value;

            // DuckDuckGo wraps URLs in a redirect; extract the actual URL.
            var uddgMatch = UddgRegex().Match(link);
            if (uddgMatch.Success)
            {
                link = Uri.UnescapeDataString(uddgMatch.Groups[1].Value);
            }

            var snippet = i < snippets.Count
                ? tagStripper.Replace(snippets[i].Groups[1].Value, "").Trim()
                : "";

            sb.AppendLine($"[{i + 1}] {title}");
            sb.AppendLine($"    URL: {link}");
            if (!string.IsNullOrEmpty(snippet))
            {
                sb.AppendLine($"    {snippet}");
            }

            sb.AppendLine();
        }

        return sb.ToString();
    }

    [GeneratedRegex(@"<a[^>]+href=""([^""]+)""[^>]+class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex ResultRegex();

    [GeneratedRegex(@"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex TagStripperRegex();

    [GeneratedRegex(@"uddg=([^&]+)")]
    private static partial Regex UddgRegex();
}

/// <summary>A simple in-memory notepad for the agent to store research findings.</summary>
sealed class Notepad
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note with a title and content. Use this to record key findings from web searches.")]
    public string TakeNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content/body of the note")] string content)
    {
        _notes.Add((title, content));
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"── Note {i + 1}: {_notes[i].Title} ──");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

