 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // ── Chat client (MEAI abstraction over OpenAI provider) ────────────────────────

 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // ── Tools ──────────────────────────────────────────────────────────────────────

 var notepad = new Notepad();
 var webSearch = new WebSearch();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(webSearch.SearchAsync),
     AIFunctionFactory.Create(notepad.TakeNote),
     AIFunctionFactory.Create(notepad.GetNotes),
 };

 // ── Agent ──────────────────────────────────────────────────────────────────────

 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An agent that researches a topic by searching the web and taking notes.",
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
             Tools = [.. tools],
         },
     });

 // ── Interactive loop ───────────────────────────────────────────────────────────

 Console.WriteLine("╔══════════════════════════════════════════════════════════════╗");
 Console.WriteLine("║              Research Agent  ·  Powered by MAF              ║");
 Console.WriteLine("╠══════════════════════════════════════════════════════════════╣");
 Console.WriteLine("║  Enter a topic to research. The agent will search the web,  ║");
 Console.WriteLine("║  take notes, and provide a summary.                         ║");
 Console.WriteLine("║  Type 'quit' to exit.                                       ║");
 Console.WriteLine("╚══════════════════════════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Research topic> ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
     {
         break;
     }

     notepad.Clear();

     var prompt = $"""
         Research the following topic: "{topic}"

         Follow these steps:
         1. Search the web for the topic using multiple relevant queries (at least 2-3 searches).
         2. As you find useful information, use the TakeNote tool to save key findings.
            Each note should have a descriptive title and concise content.
         3. After gathering enough information, use GetNotes to review all your notes.
         4. Provide a well-structured summary of your research findings, citing the
            sources of information where possible.
         """;

     List<ChatMessage> messages = [new(ChatRole.User, prompt)];

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("\n  Researching… (the agent is searching and taking notes)\n");
     Console.ResetColor();

     try
     {
         var session = await agent.CreateSessionAsync();
         var response = await agent.RunAsync(messages, session);

         Console.ForegroundColor = ConsoleColor.Green;
         Console.WriteLine("── Research Summary ───────────────────────────────────────────");
         Console.ResetColor();
         Console.WriteLine(response.Text);
         Console.WriteLine();
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"Error: {ex.Message}");
         Console.ResetColor();
     }
 }

 Console.WriteLine("Goodbye!");

